// Generated by scripts/play/export_looks.py from the app's BoardTheme.swift. Do not edit.
// Every board look in the app; the browser shows the one the friend who sent the link uses.

export const LOOKS = ["blueprint", "bordeaux", "classic", "drift", "faberge", "gilded", "midnight", "neon", "noir", "portoro", "pulse", "sculpted", "singularity", "spark", "vector"];
export const DEFAULT_LOOK = "gilded";

/** Shows a look on every board on the page: the app's default for a game without one. */
export function setLook(id) {
  const look = LOOKS.includes(id) ? id : DEFAULT_LOOK;
  if (document.documentElement.dataset.look !== look) document.documentElement.dataset.look = look;
  return look;
}
